#!/usr/bin/env python3
# tools/lint/gen_experiments_index.py — experiments/INDEX.md generator (org STAGE2, 2026-07-06)
#
# Walks every experiments/{active,sealed,archive}/**/MANIFEST.md and renders a single
# auto-generated registry table (cell / tier / status / campaign / #durable /
# artifact-pointers / snapshot-role). This SUPERSEDES the former single-body REGISTRY that
# check_manifest.py pinned; consistency between the per-cell manifests and this INDEX is
# enforced by tools/lint/check_index_consistency.py.
#
# IDEMPOTENT: the output is a pure function of the manifests on disk (no timestamps, stable
# sort) -> running the generator twice yields a byte-identical file.
#
#   gen_experiments_index.py            # (re)write experiments/INDEX.md
#   gen_experiments_index.py --check    # exit 1 if the on-disk INDEX.md is stale
#   gen_experiments_index.py --stdout   # print to stdout, do not write
#   gen_experiments_index.py --self-test

import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import _manifest_common as mc  # noqa: E402

INDEX_REL = "experiments/INDEX.md"


def _esc(text):
    """Make a free-text field safe for a one-line Markdown table cell."""
    return (text or "").replace("|", "\\|").replace("\n", " ").strip()


def _snapshot(role, width=140):
    role = _esc(role)
    if len(role) > width:
        role = role[: width - 1].rstrip() + "…"
    return role or "—"


def render(root):
    cells = mc.all_cells(root)

    # per-tier counts for the summary line.
    counts = {}
    for c in cells:
        counts[c["tier"]] = counts.get(c["tier"], 0) + 1
    summary = ", ".join(f"{t}={counts.get(t, 0)}" for t in mc.TIERS)

    lines = []
    lines.append("# experiments/ INDEX — auto-generated registry")
    lines.append("")
    lines.append("> **Do not hand-edit.** Generated by `tools/lint/gen_experiments_index.py` from")
    lines.append("> every `experiments/{active,sealed,archive}/**/MANIFEST.md`. Run the generator to")
    lines.append("> refresh; consistency is gated by `tools/lint/check_index_consistency.py`.")
    lines.append("> Old→new path map: `experiments/archive/MOVES.md`.")
    lines.append("")
    lines.append(f"**{len(cells)} cells** ({summary}).")
    lines.append("")
    lines.append("| tier | cell | status | campaign | durable | artifact pointers | snapshot |")
    lines.append("|---|---|---|---|---:|---|---|")
    for c in cells:
        ptrs = mc.artifact_pointers(c["durable"])
        # show artifact-pointer basenames (relative to cell) to keep the cell compact.
        ptr_names = [os.path.relpath(p, c["reldir"]) for p in ptrs]
        ptr_cell = ", ".join(f"`{n}`" for n in ptr_names) if ptr_names else "—"
        lines.append(
            f"| {c['tier']} | `{_esc(c['cell'])}` | {c['status']} | {_esc(c['campaign']) or '—'} "
            f"| {len(c['durable'])} | {ptr_cell} | {_snapshot(c['role'])} |"
        )
    lines.append("")
    return "\n".join(lines) + "\n"


def self_test():
    """Exercise the pure renderers on synthetic fields (no tree access)."""
    cases = [
        ("plain", "abc", "abc"),
        ("pipe escaped", "a|b", "a\\|b"),
        ("newline flattened", "a\nb", "a b"),
        ("trim", "  x  ", "x"),
    ]
    ok = True
    for name, raw, expect in cases:
        got = _esc(raw)
        mark = "PASS" if got == expect else "FAIL"
        ok = ok and got == expect
        print(f"  [{mark}] _esc {name!r}: {got!r} (expect {expect!r})")
    # snapshot truncation + empty fallback
    long = "y" * 300
    snap = _snapshot(long, width=50)
    t1 = len(snap) <= 50 and snap.endswith("…")
    print(f"  [{'PASS' if t1 else 'FAIL'}] _snapshot truncates to width+ellipsis (len={len(snap)})")
    t2 = _snapshot("") == "—"
    print(f"  [{'PASS' if t2 else 'FAIL'}] _snapshot empty -> em-dash")
    ok = ok and t1 and t2
    print("SELF-TEST:", "GREEN" if ok else "RED")
    return 0 if ok else 1


def main(argv):
    if "--self-test" in argv:
        return self_test()
    root = mc.repo_root()
    content = render(root)
    if "--stdout" in argv:
        sys.stdout.write(content)
        return 0
    index_path = os.path.join(root, INDEX_REL)
    if "--check" in argv:
        cur = ""
        if os.path.exists(index_path):
            with open(index_path, encoding="utf-8") as f:
                cur = f.read()
        if cur == content:
            print(f"OK: {INDEX_REL} is up to date ({content.count(chr(10))} lines).")
            return 0
        print(f"RED: {INDEX_REL} is STALE. Regenerate with tools/lint/gen_experiments_index.py.")
        return 1
    with open(index_path, "w", encoding="utf-8") as f:
        f.write(content)
    n = len(mc.all_cells(root))
    print(f"WROTE {INDEX_REL} ({n} cells).")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
